	/** Called on the Swing thread when the Refresh button is clicked; it must not block. */
	void setRefreshAction(Runnable action)
	{
		refreshAction = action;
	}

	/** Safe to call from any thread. */
	void update(List<PromotionRow> newRows, Summary newSummary)
	{
		pendingRows = newRows;
		pendingSummary = newSummary;
		SwingUtilities.invokeLater(() ->
		{
			if (!rebuildTimer.isRunning())
			{
				rebuildTimer.start();
			}
		});
	}

	/** Restarts the timers that {@link #stop()} stopped, for when the plugin is turned back on. */
	void start()
	{
		SwingUtilities.invokeLater(ageTimer::start);
	}

	void stop()
	{
		SwingUtilities.invokeLater(() ->
		{
			rebuildTimer.stop();
			ageTimer.stop();
		});
	}

	/** Swing thread only. */
	private void rebuild()
	{
		readyValue.setText(String.valueOf(summary.getDueCount()));
		checkedValue.setText(summary.getCheckedCount() + "/" + summary.getCheckableCount());
		failedValue.setText(String.valueOf(summary.getFailedCount()));
		membersValue.setText(String.valueOf(summary.getMemberCount()));

		if (summary.getMemberCount() == 0)
		{
			note.setText("Log in and open your clan to load members");
		}
		else if (!summary.isWiseOldManEnabled())
		{
			note.setText("Turn on Wise Old Man lookups in the settings");
		}
		else
		{
			note.setText(summary.getGroupStatus() == null ? " " : summary.getGroupStatus());
			note.setToolTipText(summary.getGroupStatus());
		}
		updateLastChecked();
		updateRefreshButton();

		String query = search.getText().trim().toLowerCase(Locale.ROOT);
		List<PromotionRow> shown = new ArrayList<>();
		for (PromotionRow row : rows)
		{
			if (matchesTab(row, selectedTab) && (query.isEmpty() || row.getName().toLowerCase(Locale.ROOT).contains(query)))
			{
				shown.add(row);
			}
		}
		shown.sort(Comparator.comparing((PromotionRow row) -> row.getStatus().ordinal())
			.thenComparing(PromotionRow::getName, String.CASE_INSENSITIVE_ORDER));

		list.removeAll();
		int count = Math.min(MAX_ROWS, shown.size());
		for (int i = 0; i < count; i++)
		{
			list.add(buildRow(shown.get(i)));
			list.add(gap(6));
		}
		if (shown.isEmpty())
		{
			JLabel empty = new JLabel(rows.isEmpty() ? "No clan members yet" : "Nobody here", SwingConstants.CENTER);
			empty.setFont(FontManager.getRunescapeSmallFont());
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			empty.setMaximumSize(new Dimension(Integer.MAX_VALUE, empty.getPreferredSize().height + 14));
			empty.setBorder(BorderFactory.createEmptyBorder(14, 0, 0, 0));
			list.add(empty);
		}
		if (shown.size() > count)
		{
			JLabel more = new JLabel("+" + (shown.size() - count) + " more: use search", SwingConstants.CENTER);
			more.setFont(FontManager.getRunescapeSmallFont());
			more.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			more.setMaximumSize(new Dimension(Integer.MAX_VALUE, more.getPreferredSize().height));
			list.add(more);
		}
		// A box layout shifts every row if any one of them is aligned differently (the "more" and
		// "nobody here" labels used to be centred), so force them all to the same alignment.
		for (Component child : list.getComponents())
		{
			if (child instanceof JComponent)
			{
				((JComponent) child).setAlignmentX(Component.LEFT_ALIGNMENT);
			}
		}
		list.revalidate();
		list.repaint();
	}

	private static boolean matchesTab(PromotionRow row, String tab)
	{
		switch (tab)
		{
			case "Ready":
				return row.getStatus() == PromotionStatus.READY;
			case "Later":
				return row.getStatus() == PromotionStatus.NOT_READY;
			case "Failed":
				return row.getStatus() == PromotionStatus.FAILED;
			default:
				return true;
		}
	}

	/** A dark card with the member's name and status, their ranks and months, and progress bars. */
	private static JPanel buildRow(PromotionRow row)
	{
		Color accent = statusColor(row.getStatus());

		JPanel panel = new JPanel(new BorderLayout(0, 4));
		panel.setBackground(CARD_BACKGROUND);
		panel.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(2, 2, 2, 2, CARD_BORDER),
			BorderFactory.createEmptyBorder(6, 8, 6, 8)));
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);

		// The member's clan rank icon from the game, or a coloured status dot until it has loaded
		Icon icon = row.getRankIcon() != null ? new ImageIcon(row.getRankIcon()) : new StatusIcon(row.getStatus(), accent);
		JLabel name = new JLabel(row.getName(), icon, JLabel.LEFT);
		name.setIconTextGap(6);
		name.setFont(FontManager.getRunescapeBoldFont());
		name.setForeground(Color.WHITE);

		JLabel status = new JLabel(statusText(row));
		status.setFont(FontManager.getRunescapeSmallFont());
		status.setForeground(accent);

		boolean hasBars = row.getRequiredMonths() > 0 || row.getRequiredXpMillions() > 0;
		JLabel details = new JLabel(detailsText(row, !hasBars));
		details.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.PLAIN));
		details.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		JPanel top = new JPanel(new BorderLayout());
		top.setOpaque(false);
		top.add(name, BorderLayout.WEST);
		top.add(status, BorderLayout.EAST);

		JPanel south = new JPanel();
		south.setOpaque(false);
		south.setLayout(new BoxLayout(south, BoxLayout.Y_AXIS));
		details.setAlignmentX(Component.LEFT_ALIGNMENT);
		south.add(details);
		if (hasBars)
		{
			double monthFraction = row.getRequiredMonths() == 0 ? 1 : (double) row.getMonths() / row.getRequiredMonths();
			Double xpFraction = row.getXpGained() == null ? null
				: row.getRequiredXpMillions() == 0 ? Double.valueOf(1)
				: Double.valueOf(row.getXpGained() / 1_000_000.0 / row.getRequiredXpMillions());
			south.add(gap(2));
			south.add(new MiniBar(row.getMonths() + " mo", monthFraction));
			south.add(new MiniBar(row.getXpGained() == null ? "--" : formatXp(row.getXpGained()), xpFraction));
		}

		panel.add(top, BorderLayout.NORTH);
		panel.add(south, BorderLayout.SOUTH);
		if (row.getDetail() != null)
		{
			panel.setToolTipText(row.getDetail());
		}
		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, panel.getPreferredSize().height));
		return panel;
	}

	/** A small round icon in the status colour, with a glyph drawn in code so it needs no image files. */
	private static final class StatusIcon implements Icon
	{
		private static final int SIZE = 12;
		private final PromotionStatus status;
		private final Color color;

		StatusIcon(PromotionStatus status, Color color)
		{
			this.status = status;
			this.color = color;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(color);
			g2.fillOval(x, y, SIZE, SIZE);
			g2.setColor(CARD_BACKGROUND);
			g2.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			int cx = x + SIZE / 2;
			int cy = y + SIZE / 2;
			switch (status)
			{
				case READY:
					g2.drawLine(cx - 3, cy + 1, cx, cy - 2);
					g2.drawLine(cx, cy - 2, cx + 3, cy + 1);
					break;
				case FAILED:
					g2.drawLine(cx, cy - 3, cx, cy + 0);
					g2.drawLine(cx, cy + 2, cx, cy + 2);
					break;
				case NOT_READY:
					g2.drawLine(cx - 3, cy, cx + 3, cy);
					break;
				default:
					g2.drawLine(cx - 3, cy, cx - 3, cy);
					g2.drawLine(cx, cy, cx, cy);
					g2.drawLine(cx + 3, cy, cx + 3, cy);
					break;
			}
			g2.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return SIZE;
		}

		@Override
		public int getIconHeight()
		{
			return SIZE;
		}
	}

	/** A labelled thin progress bar: green once the requirement is met, amber while it isn't, empty with no data. */
	private static final class MiniBar extends JComponent
	{
		/** Tall enough for the value text; the bar itself is thinner and centred in it */
		private static final int HEIGHT = 14;
		private static final int BAR_HEIGHT = 7;
		private static final int LABEL_WIDTH = 38;
		private final String label;
		private final Double fraction;

		MiniBar(String label, Double fraction)
		{
			this.label = label;
			this.fraction = fraction;
			setAlignmentX(Component.LEFT_ALIGNMENT);
			setPreferredSize(new Dimension(10, HEIGHT));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
			setMinimumSize(new Dimension(10, HEIGHT));
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setFont(FontManager.getRunescapeSmallFont());
			g2.setColor(ColorScheme.LIGHT_GRAY_COLOR);
			java.awt.FontMetrics metrics = g2.getFontMetrics();
			int baseline = (getHeight() + metrics.getAscent() - metrics.getDescent()) / 2;
			g2.drawString(label, 0, baseline);

			int barX = LABEL_WIDTH;
			int barY = (getHeight() - BAR_HEIGHT) / 2;
			int barWidth = Math.max(1, getWidth() - barX);
			g2.setColor(CARD_BORDER);
			g2.fillRoundRect(barX, barY, barWidth, BAR_HEIGHT, 4, 4);
			if (fraction != null)
			{
				double clamped = Math.max(0, Math.min(1, fraction));
				g2.setColor(fraction >= 1 ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.PROGRESS_INPROGRESS_COLOR);
				g2.fillRoundRect(barX, barY, (int) Math.round(barWidth * clamped), BAR_HEIGHT, 4, 4);
			}
			g2.dispose();
		}
	}

	static String statusText(PromotionRow row)
	{
		switch (row.getStatus())
		{
			case PENDING:
				return "Waiting";
			case FAILED:
				return "Failed";
			case UNKNOWN_RANK:
				return "No rank";
			case MAX_RANK:
				return "Top";
			default:
				return row.getStatus().getLabel();
		}
	}

	/** The rank line; the months and XP are added only when the card has no progress bars to show them. */
	static String detailsText(PromotionRow row, boolean includeStats)
	{
		StringBuilder text = new StringBuilder(row.getCurrentRank() == null ? "Unknown rank" : row.getCurrentRank());
		// The RuneScape font has no arrow glyph, so use a plain ">"
		if (row.getNextRank() != null)
		{
			text.append(" > ").append(row.getNextRank());
		}
		if (includeStats)
		{
			text.append(" \u00B7 ").append(row.getMonths()).append(" mo");
			if (row.getXpGained() != null)
			{
				text.append(" \u00B7 ").append(formatXp(row.getXpGained()));
			}
		}
		return text.toString();
	}

	static String formatXp(long xp)
	{
		return String.format(Locale.ENGLISH, "%.1fM", xp / 1_000_000.0);
	}

	private static Color statusColor(PromotionStatus status)
	{
		switch (status)
		{
			case READY:
				return ColorScheme.PROGRESS_COMPLETE_COLOR;
			case FAILED:
				return ColorScheme.PROGRESS_ERROR_COLOR;
			case NOT_READY:
				return ColorScheme.PROGRESS_INPROGRESS_COLOR;
			case IGNORED:
				return ColorScheme.BRAND_ORANGE;
			default:
				return ColorScheme.MEDIUM_GRAY_COLOR;
		}
	}
}

package com.clanpromotionhelper;

import java.awt.Image;
import lombok.Value;

/**
 * One clan member as shown in the sidebar.
 */
@Value
class PromotionRow
{
	String name;
	String currentRank;
	/** The rank they'd move up to; null when there isn't one */
	String nextRank;
	int months;
	/** What the next rank needs, for the progress bars; 0 when there is no next rank */
	int requiredMonths;
	double requiredXpMillions;
	/** XP gained since joining; null until a lookup succeeds */
	Long xpGained;
	PromotionStatus status;
	/** Why a lookup failed, for the tooltip */
	String detail;
	/** The game's icon for the member's clan rank; null until RuneLite has loaded it */
	Image rankIcon;
	/** When this member's XP was last looked up (milliseconds since the epoch); 0 if never */
	long checkedAt;
}

package com.clanpromotionhelper;

/**
 * Why a clan member is or isn't due a promotion. Declared in the order the sidebar lists them.
 */
enum PromotionStatus
{
	READY("Ready"),
	NOT_READY("Not ready"),
	PENDING("Waiting for XP"),
	FAILED("Lookup failed"),
	IGNORED("Ignored"),
	UNKNOWN_RANK("Rank not in table"),
	MAX_RANK("Top rank"),
	/** Only produced by {@link RankRules#evaluate}; the plugin reports it as PENDING or FAILED. */
	NO_XP("No XP data");

	private final String label;

	PromotionStatus(String label)
	{
		this.label = label;
	}

	String getLabel()
	{
		return label;
	}
}

package com.clanpromotionhelper;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.Value;

/**
 * The clan's promotion ladder: each rank needs a minimum number of whole months in the clan
 * and a minimum amount of XP gained since joining. A member qualifies for the next rank only.
 */
public final class RankRules
{
	static final String DEFAULT_TABLE = String.join("\n",
		"Thief:0:0",
		"Recruit:1:0.1",
		"Corporal:2:0.5",
		"Sergeant:3:1",
		"Lieutenant:4:2",
		"Captain:5:3",
		"General:6:8",
		"Officer:9:12",
		"Commander:12:20",
		"Colonel:15:25",
		"Brigadier:17:30",
		"Admiral:20:50",
		"Marshal:24:75");

	@Value
	static class Rank
	{
		String name;
		int months;
		double xpMillions;
	}

	private final List<Rank> ranks;
	private final List<String> errors;

	private RankRules(List<Rank> ranks, List<String> errors)
	{
		this.ranks = Collections.unmodifiableList(ranks);
		this.errors = Collections.unmodifiableList(errors);
	}

	/**
	 * Parses one rank per line as {@code Name:months:xpMillions}, lowest rank first.
	 * Blank lines are skipped; malformed ones are skipped and reported by {@link #getErrors}.
	 */
	static RankRules parse(String table)
	{
		List<Rank> ranks = new ArrayList<>();
		List<String> errors = new ArrayList<>();
		if (table == null)
		{
			return new RankRules(ranks, errors);
		}

		String[] lines = table.split("\\r?\\n");
		for (int i = 0; i < lines.length; i++)
		{
			String line = lines[i].trim();
			if (line.isEmpty())
			{
				continue;
			}

			String error = null;
			String[] parts = line.split(":");
			if (parts.length != 3 || parts[0].trim().isEmpty())
			{
				error = "expected Rank:months:XP";
			}
			else
			{
				try
				{
					int months = Integer.parseInt(parts[1].trim());
					double xp = Double.parseDouble(parts[2].trim());
					if (months < 0 || xp < 0)
					{
						error = "numbers can't be negative";
					}
					else if (Double.isNaN(xp) || Double.isInfinite(xp))
					{
						error = "a number doesn't parse";
					}
					else
					{
						ranks.add(new Rank(parts[0].trim(), months, xp));
					}
				}
				catch (NumberFormatException e)
				{
					error = "a number doesn't parse";
				}
			}

			if (error != null)
			{
				errors.add("Line " + (i + 1) + " (" + line + "): " + error);
			}
		}

		return new RankRules(ranks, errors);
	}

	List<Rank> getRanks()
	{
		return ranks;
	}

	/** One message per line {@link #parse} skipped, saying which line and why. */
	List<String> getErrors()
	{
		return errors;
	}

	/** Whether a member with this rank can move up the ladder: not true of top ranks or ones the table doesn't have, such as staff. */
	boolean canBePromoted(String currentRank)
	{
		PromotionStatus status = evaluate(currentRank, null, null, LocalDate.MIN).getStatus();
		return status != PromotionStatus.UNKNOWN_RANK && status != PromotionStatus.MAX_RANK;
	}

	/**
	 * Whole months between the join date and today, one fewer if this month's join day hasn't arrived yet.
	 */
	static int monthsInClan(LocalDate joinDate, LocalDate today)
	{
		int months = (today.getYear() - joinDate.getYear()) * 12 + (today.getMonthValue() - joinDate.getMonthValue());
		if (today.getDayOfMonth() < joinDate.getDayOfMonth())
		{
			months -= 1;
		}
		return Math.max(0, months);
	}

	@Value
	static class Evaluation
	{
		PromotionStatus status;
		/** The rank after the member's current one; null for unknown or top ranks */
		String nextRank;
		int months;
		int requiredMonths;
		double requiredXpMillions;
	}

	/**
	 * Returns the rank the member should be promoted to, or null if they don't qualify yet,
	 * are already at the top rank, hold a rank that isn't in the table, or have no XP data.
	 */
	String nextRankFor(String currentRank, LocalDate joinDate, Long xpGained, LocalDate today)
	{
		Evaluation evaluation = evaluate(currentRank, joinDate, xpGained, today);
		return evaluation.getStatus() == PromotionStatus.READY ? evaluation.getNextRank() : null;
	}

	/**
	 * Works out whether a member is due a promotion and, if not, why not.
	 */
	Evaluation evaluate(String currentRank, LocalDate joinDate, Long xpGained, LocalDate today)
	{
		int months = joinDate == null ? 0 : monthsInClan(joinDate, today);

		int currentIndex = -1;
		if (currentRank != null)
		{
			for (int i = 0; i < ranks.size(); i++)
			{
				if (ranks.get(i).getName().equalsIgnoreCase(currentRank.trim()))
				{
					currentIndex = i;
					break;
				}
			}
		}

		if (currentIndex == -1)
		{
			return new Evaluation(PromotionStatus.UNKNOWN_RANK, null, months, 0, 0);
		}

		if (currentIndex + 1 >= ranks.size())
		{
			return new Evaluation(PromotionStatus.MAX_RANK, null, months, 0, 0);
		}

		Rank next = ranks.get(currentIndex + 1);
		if (joinDate == null || xpGained == null)
		{
			return new Evaluation(PromotionStatus.NO_XP, next.getName(), months, next.getMonths(), next.getXpMillions());
		}

		boolean ready = months >= next.getMonths() && xpGained / 1_000_000.0 >= next.getXpMillions();
		return new Evaluation(ready ? PromotionStatus.READY : PromotionStatus.NOT_READY,
			next.getName(), months, next.getMonths(), next.getXpMillions());
	}
}

