/**
 * Sidebar editor for the rank ladder, based on the one ItsMajorSpace contributed in pull request #1. It reads and writes the
 * same text setting as the plugin's configuration panel, so either can be used, and checks every rank before
 * saving anything.
 */
@Singleton
class RulesEditorPanel extends JPanel
{
	private static final Border FIELD_BORDER = BorderFactory.createCompoundBorder(
		BorderFactory.createMatteBorder(1, 1, 1, 1, CARD_BORDER), BorderFactory.createEmptyBorder(2, 4, 2, 4));
	private static final Border CARD = BorderFactory.createCompoundBorder(
		BorderFactory.createMatteBorder(2, 2, 2, 2, CARD_BORDER), BorderFactory.createEmptyBorder(6, 8, 6, 8));
	private static final Border CARD_ERROR = BorderFactory.createCompoundBorder(
		BorderFactory.createMatteBorder(2, 2, 2, 2, ColorScheme.PROGRESS_ERROR_COLOR), BorderFactory.createEmptyBorder(6, 8, 6, 8));

	private final ConfigManager configManager;
	private final ClanPromotionHelperConfig config;
	private final JPanel ladderList = column();
	private final JLabel status = new JLabel(" ");
	private final List<LadderCard> ladder = new ArrayList<>();
	private Supplier<List<String>> clanRanks = Collections::emptyList;
	private Runnable onClose = () -> { };

	@Inject
	RulesEditorPanel(ConfigManager configManager, ClanPromotionHelperConfig config)
	{
		this.configManager = configManager;
		this.config = config;
		setLayout(new BorderLayout());
		setBackground(PANEL_BACKGROUND);

		JPanel content = new PromotionPanel.ViewportWidthPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(PANEL_BACKGROUND);
		content.setBorder(BorderFactory.createEmptyBorder(0, 8, 8, 7));
		content.add(heading("Rank ladder", "Lowest first. A member can move up one rank at a time. "
			+ "Leave a box at 0 to not require it."));
		content.add(ladderList);
		JPanel ladderButtons = new JPanel(new GridLayout(1, 2, 6, 0));
		ladderButtons.setOpaque(false);
		ladderButtons.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
		ladderButtons.add(addButton("Add rank", () -> addLadder(new RankRules.Rank("", 0, 0))));
		JButton fill = addButton("Fill from clan", this::fillFromClan);
		fill.setToolTipText("List your clan's ranks in their in-game order, keeping the requirements already set for them");
		ladderButtons.add(fill);
		content.add(ladderButtons);
		leftAlign(content);
		add(PromotionPanel.darkScroll(content), BorderLayout.CENTER);

		JButton save = new JButton("Save");
		JButton cancel = new JButton("Cancel");
		styleButton(save);
		styleButton(cancel);
		save.addActionListener(e -> save());
		cancel.addActionListener(e -> onClose.run());
		JPanel buttons = new JPanel(new GridLayout(1, 2, 6, 0));
		buttons.setOpaque(false);
		buttons.add(save);
		buttons.add(cancel);

		status.setFont(FontManager.getRunescapeSmallFont());
		status.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
		JPanel footer = new JPanel(new BorderLayout(0, 4));
		footer.setBackground(PANEL_BACKGROUND);
		footer.setBorder(BorderFactory.createEmptyBorder(6, 8, 8, 10));
		footer.add(status, BorderLayout.NORTH);
		footer.add(buttons, BorderLayout.CENTER);
		add(footer, BorderLayout.SOUTH);
	}

	/** Where the clan's rank titles come from, lowest first; read whenever Fill from clan is pressed. */
	void setClanRanks(Supplier<List<String>> clanRanks)
	{
		this.clanRanks = clanRanks;
	}

	void setOnClose(Runnable onClose)
	{
		this.onClose = onClose;
	}

	/** Reloads the ladder from the settings, dropping any unsaved edits. Swing thread only. */
	void open()
	{
		RankRules ranks = RankRules.parse(config.rankRequirements());
		ladder.clear();
		ladderList.removeAll();
		for (RankRules.Rank rank : ranks.getRanks())
		{
			addLadder(rank);
		}

		// Saving rewrites the setting from the cards, so lines the editor couldn't load would be lost
		int unreadable = ranks.getErrors().size();
		setStatus(unreadable == 0 ? " " : unreadable + " unreadable line" + (unreadable == 1 ? "" : "s") + " will be removed on save",
			unreadable == 0 ? null : String.join("\n", ranks.getErrors()));
		refresh();
	}

	private void save()
	{
		List<String> problems = new ArrayList<>();
		List<String> lines = new ArrayList<>();
		for (int i = 0; i < ladder.size(); i++)
		{
			LadderCard card = ladder.get(i);
			String line = card.toLine();
			String name = card.name.getText().trim();
			String problem = name.isEmpty() ? "needs a name"
				: name.contains(":") ? "name can't contain \":\""
				: RankRules.parse(line).getErrors().isEmpty() ? null : "check the numbers";
			card.mark(problem);
			if (problem != null)
			{
				problems.add("Rank " + (i + 1) + ": " + problem);
			}
			lines.add(line);
		}

		if (!problems.isEmpty())
		{
			setStatus(problems.size() + " problem" + (problems.size() == 1 ? "" : "s") + " (hover)", String.join("\n", problems));
			refresh();
			return;
		}

		configManager.setConfiguration(ClanPromotionHelperConfig.GROUP, "rankRequirements", String.join("\n", lines));
		setStatus(" ", null);
		onClose.run();
	}

	/**
	 * Replaces the ladder with the clan's in-game ranks, lowest first, keeping each existing card's requirements.
	 * Nothing is saved until Save, so Cancel undoes it.
	 */
	void fillFromClan()
	{
		List<String> titles = clanRanks.get();
		if (titles.isEmpty())
		{
			setStatus("Log in and open your clan to load its ranks", null);
			return;
		}

		Map<String, LadderCard> existing = new LinkedHashMap<>();
		for (LadderCard card : ladder)
		{
			existing.putIfAbsent(card.name.getText().trim().toLowerCase(Locale.ROOT), card);
		}

		List<LadderCard> filled = new ArrayList<>();
		for (String title : titles)
		{
			LadderCard card = existing.remove(title.toLowerCase(Locale.ROOT));
			if (card == null)
			{
				card = new LadderCard(new RankRules.Rank(title, 0, 0));
			}
			card.name.setText(title);
			filled.add(card);
		}
		ladder.clear();
		ladder.addAll(filled);
		relist();

		List<String> dropped = new ArrayList<>();
		for (LadderCard card : existing.values())
		{
			if (!card.name.getText().trim().isEmpty())
			{
				dropped.add(card.name.getText().trim());
			}
		}
		if (dropped.isEmpty())
		{
			setStatus("Ranks filled in: check them, then Save", null);
			status.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		}
		else
		{
			setStatus("Removed " + dropped.size() + " rank" + (dropped.size() == 1 ? "" : "s") + " not in the clan (hover)",
				String.join("\n", dropped));
		}
	}

	private void setStatus(String text, String tooltip)
	{
		status.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
		status.setText(text);
		status.setToolTipText(tooltip == null ? null : "<html>" + escape(tooltip).replace("\n", "<br>") + "</html>");
	}

	private void addLadder(RankRules.Rank rank)
	{
		LadderCard card = new LadderCard(rank);
		ladder.add(card);
		ladderList.add(card);
		ladderList.add(gap(6));
		refresh();
	}

	private void moveLadder(LadderCard card, int by)
	{
		int from = ladder.indexOf(card);
		int to = from + by;
		if (to < 0 || to >= ladder.size())
		{
			return;
		}
		Collections.swap(ladder, from, to);
		relist();
	}

	private void relist()
	{
		ladderList.removeAll();
		for (LadderCard card : ladder)
		{
			ladderList.add(card);
			ladderList.add(gap(6));
		}
		refresh();
	}

	private void refresh()
	{
		leftAlign(this);
		revalidate();
		repaint();
	}

	/** One rung of the ladder: name and order on top, then months and XP. */
	private final class LadderCard extends JPanel
	{
		private final JTextField name = field(20);
		private final JTextField months = field(3);
		private final JTextField xp = field(4);

		LadderCard(RankRules.Rank rank)
		{
			super(new BorderLayout(0, 4));
			setBackground(CARD_BACKGROUND);
			setBorder(CARD);
			name.setText(rank.getName());
			months.setText(String.valueOf(rank.getMonths()));
			xp.setText(BigDecimal.valueOf(rank.getXpMillions()).stripTrailingZeros().toPlainString());

			JPanel top = new JPanel(new BorderLayout(4, 0));
			top.setOpaque(false);
			top.add(name, BorderLayout.CENTER);
			top.add(iconButtons(
				iconButton(Glyph.UP, "Move up", () -> moveLadder(this, -1)),
				iconButton(Glyph.DOWN, "Move down", () -> moveLadder(this, 1)),
				iconButton(Glyph.CROSS, "Remove", () ->
				{
					ladder.remove(this);
					relist();
				})), BorderLayout.EAST);

			JPanel numbers = new JPanel(new GridLayout(1, 2, 4, 0));
			numbers.setOpaque(false);
			numbers.add(labelled("Months", months));
			numbers.add(labelled("XP (millions)", xp));

			add(top, BorderLayout.NORTH);
			add(numbers, BorderLayout.CENTER);
		}

		String toLine()
		{
			return name.getText().trim() + ":" + months.getText().trim() + ":" + xp.getText().trim();
		}

		void mark(String problem)
		{
			setBorder(problem == null ? CARD : CARD_ERROR);
			setToolTipText(problem);
		}
	}

	private static JPanel column()
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setOpaque(false);
		return panel;
	}

	private static JPanel heading(String title, String description)
	{
		JPanel panel = new JPanel(new BorderLayout(0, 2));
		panel.setOpaque(false);
		panel.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
		JLabel titleLabel = new JLabel(title);
		titleLabel.setFont(FontManager.getRunescapeBoldFont());
		titleLabel.setForeground(Color.WHITE);
		// html with a fixed width so the description wraps inside the sidebar instead of being cut off
		JLabel descriptionLabel = new JLabel("<html><div style='width:150px'>" + escape(description) + "</div></html>");
		descriptionLabel.setFont(FontManager.getRunescapeSmallFont());
		descriptionLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		panel.add(titleLabel, BorderLayout.NORTH);
		panel.add(descriptionLabel, BorderLayout.CENTER);
		return panel;
	}

	private static JButton addButton(String text, Runnable action)
	{
		JButton button = new JButton(text);
		styleButton(button);
		button.addActionListener(e -> action.run());
		return button;
	}

	private static JButton iconButton(Glyph glyph, String tooltip, Runnable action)
	{
		// Drawn rather than typed: RuneLite's fonts, which buttons use by default, have no arrow or cross characters
		JButton button = new JButton(new GlyphIcon(glyph, ColorScheme.LIGHT_GRAY_COLOR));
		button.setDisabledIcon(new GlyphIcon(glyph, ColorScheme.MEDIUM_GRAY_COLOR));
		button.setToolTipText(tooltip);
		button.setFocusPainted(false);
		button.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		button.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		button.setBorder(BorderFactory.createMatteBorder(1, 1, 1, 1, CARD_BORDER));
		button.setPreferredSize(new Dimension(20, 20));
		button.addActionListener(e -> action.run());
		return button;
	}

	private enum Glyph
	{
		UP, DOWN, CROSS
	}

	/** A small up arrow, down arrow or cross, drawn with lines so it looks the same in any font. */
	private static final class GlyphIcon implements Icon
	{
		private static final int SIZE = 8;
		private final Glyph glyph;
		private final Color color;

		GlyphIcon(Glyph glyph, Color color)
		{
			this.glyph = glyph;
			this.color = color;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(color);
			switch (glyph)
			{
				case UP:
					g2.fillPolygon(new int[]{x, x + SIZE / 2, x + SIZE}, new int[]{y + SIZE - 1, y + 1, y + SIZE - 1}, 3);
					break;
				case DOWN:
					g2.fillPolygon(new int[]{x, x + SIZE / 2, x + SIZE}, new int[]{y + 1, y + SIZE - 1, y + 1}, 3);
					break;
				default:
					g2.setStroke(new BasicStroke(1.5f));
					g2.drawLine(x + 1, y + 1, x + SIZE - 1, y + SIZE - 1);
					g2.drawLine(x + 1, y + SIZE - 1, x + SIZE - 1, y + 1);
					break;
			}
			g2.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return SIZE;
		}

		@Override
		public int getIconHeight()
		{
			return SIZE;
		}
	}

	private static JPanel iconButtons(JButton... buttons)
	{
		JPanel panel = new JPanel(new GridLayout(1, buttons.length, 2, 0));
		panel.setOpaque(false);
		for (JButton button : buttons)
		{
			panel.add(button);
		}
		return panel;
	}

	private static JTextField field(int columns)
	{
		JTextField field = new JTextField(columns);
		field.setFont(FontManager.getRunescapeSmallFont());
		field.setForeground(Color.WHITE);
		field.setCaretColor(Color.WHITE);
		field.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		field.setBorder(FIELD_BORDER);
		return field;
	}

	/** A box with a small grey caption above it. */
	private static JPanel labelled(String caption, JComponent box)
	{
		JPanel panel = new JPanel(new BorderLayout(0, 1));
		panel.setOpaque(false);
		JLabel label = new JLabel(caption);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		panel.add(label, BorderLayout.NORTH);
		panel.add(box, BorderLayout.CENTER);
		// Narrow sidebar: let boxes shrink rather than push the card wider than the panel
		box.setMinimumSize(new Dimension(10, box.getPreferredSize().height));
		box.setPreferredSize(new Dimension(10, box.getPreferredSize().height));
		return panel;
	}

	/** A box layout shifts every row if any one is aligned differently, so force them all left. */
	private static void leftAlign(Container container)
	{
		for (Component child : container.getComponents())
		{
			if (child instanceof JComponent)
			{
				((JComponent) child).setAlignmentX(Component.LEFT_ALIGNMENT);
			}
			if (child instanceof Container)
			{
				leftAlign((Container) child);
			}
		}
	}

	private static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.clanpromotionhelper;

/**
 * Turns "when did this happen" into short relative text such as "5 min ago".
 */
final class TimeAgo
{
	private static final long MINUTE = 60_000L;
	private static final long HOUR = 60 * MINUTE;
	private static final long DAY = 24 * HOUR;

	private TimeAgo()
	{
	}

	static String format(long nowMillis, long thenMillis)
	{
		long elapsed = Math.max(0, nowMillis - thenMillis);
		if (elapsed < MINUTE)
		{
			return "just now";
		}
		if (elapsed < HOUR)
		{
			return elapsed / MINUTE + " min ago";
		}
		if (elapsed < DAY)
		{
			return elapsed / HOUR + " h ago";
		}
		return elapsed / DAY + " d ago";
	}
}

package com.clanpromotionhelper;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Looks up how much overall XP a player gained between two dates on Wise Old Man.
 * Any non-2xx response is reported as a failure or a retry, never as 0 XP gained.
 */
@Slf4j
@Singleton
class WiseOldManClient
{
	private static final HttpUrl BASE_URL = HttpUrl.get("https://api.wiseoldman.net/v2/");
	private static final int DEFAULT_RATE_LIMIT_WAIT_SECONDS = 60;
	private static final int SERVER_ERROR_WAIT_SECONDS = 5;

	@Value
	static class Result
	{
		enum Status
		{
			OK,
			RETRY,
			FAILED
		}

		Status status;
		Long xpGained;
		/** Total XP when the window starts; null when Wise Old Man has no snapshot there */
		Long startXp;
		int retryAfterSeconds;
		String error;

		static Result ok(long xpGained, Long startXp)
		{
			return new Result(Status.OK, xpGained, startXp, 0, null);
		}

		static Result retry(int seconds, String error)
		{
			return new Result(Status.RETRY, null, null, seconds, error);
		}

		static Result failed(String error)
		{
			return new Result(Status.FAILED, null, null, 0, error);
		}
	}

	/** Every group member's current total XP, keyed by {@link XpCache#key}. */
	@Value
	static class GroupResult
	{
		boolean ok;
		Map<String, Long> exp;
		String error;
	}

	private final OkHttpClient httpClient;
	private final Gson gson;

	@Inject
	WiseOldManClient(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = httpClient;
		this.gson = gson;
	}

	/**
	 * Runs the lookup on OkHttp's thread pool and passes the result to the callback on that thread.
	 */
	void fetchXpGained(String rsn, LocalDate startDate, LocalDate endDate, String apiKey, String contact, Consumer<Result> callback)
	{
		HttpUrl url = BASE_URL.newBuilder()
			.addPathSegment("players")
			.addPathSegment(rsn)
			.addPathSegment("gained")
			.addQueryParameter("startDate", startDate.toString())
			.addQueryParameter("endDate", endDate.toString())
			.build();

		Request.Builder request = new Request.Builder()
			.url(url)
			.header("Accept", "application/json")
			.header("User-Agent", userAgent(contact));

		if (apiKey != null && !apiKey.trim().isEmpty())
		{
			request.header("x-api-key", apiKey.trim());
		}

		httpClient.newCall(request.build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Wise Old Man request for {} failed", rsn, e);
				callback.accept(Result.retry(SERVER_ERROR_WAIT_SECONDS, "Network error: " + e.getMessage()));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					String text = body == null ? "" : body.string();
					callback.accept(parse(response.code(), text, response.header("Retry-After"), gson));
				}
				catch (IOException e)
				{
					log.debug("Reading Wise Old Man response for {} failed", rsn, e);
					callback.accept(Result.retry(SERVER_ERROR_WAIT_SECONDS, "Network error: " + e.getMessage()));
				}
			}
		});
	}

	/**
	 * Fetches the whole group in one request. Failures are reported, never retried: the caller falls back
	 * to individual lookups, so a wrong group ID or a rate limit can't turn into a retry loop.
	 */
	void fetchGroup(int groupId, String apiKey, String contact, Consumer<GroupResult> callback)
	{
		HttpUrl url = BASE_URL.newBuilder()
			.addPathSegment("groups")
			.addPathSegment(String.valueOf(groupId))
			.build();

		Request.Builder request = new Request.Builder()
			.url(url)
			.header("Accept", "application/json")
			.header("User-Agent", userAgent(contact));

		if (apiKey != null && !apiKey.trim().isEmpty())
		{
			request.header("x-api-key", apiKey.trim());
		}

		httpClient.newCall(request.build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Wise Old Man group request failed", e);
				callback.accept(new GroupResult(false, new HashMap<>(), "Network error: " + e.getMessage()));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					callback.accept(parseGroup(response.code(), body == null ? "" : body.string(), gson));
				}
				catch (IOException e)
				{
					log.debug("Reading Wise Old Man group response failed", e);
					callback.accept(new GroupResult(false, new HashMap<>(), "Network error: " + e.getMessage()));
				}
			}
		});
	}

	static GroupResult parseGroup(int code, String body, Gson gson)
	{
		JsonObject root;
		try
		{
			root = gson.fromJson(body, JsonObject.class);
		}
		catch (JsonParseException | IllegalStateException e)
		{
			root = null;
		}

		if (code < 200 || code >= 300)
		{
			String message = code == 429 ? "Rate limited by Wise Old Man"
				: root != null && root.has("message") && root.get("message").isJsonPrimitive()
					? root.get("message").getAsString()
					: "Wise Old Man returned HTTP " + code;
			return new GroupResult(false, new HashMap<>(), message);
		}

		JsonElement memberships = root == null ? null : root.get("memberships");
		if (memberships == null || !memberships.isJsonArray())
		{
			return new GroupResult(false, new HashMap<>(), "Unexpected Wise Old Man response (no group members)");
		}

		Map<String, Long> exp = new HashMap<>();
		JsonArray array = memberships.getAsJsonArray();
		for (JsonElement membership : array)
		{
			JsonElement player = membership.isJsonObject() ? membership.getAsJsonObject().get("player") : null;
			if (player == null || !player.isJsonObject())
			{
				continue;
			}

			JsonObject playerObject = player.getAsJsonObject();
			JsonElement total = playerObject.get("exp");
			if (total == null || !total.isJsonPrimitive() || !total.getAsJsonPrimitive().isNumber() || total.getAsLong() <= 0)
			{
				continue;
			}

			// A member can be matched by either their lookup name or their display name
			for (String field : new String[]{"username", "displayName"})
			{
				JsonElement name = playerObject.get(field);
				if (name != null && name.isJsonPrimitive() && !name.getAsString().trim().isEmpty())
				{
					exp.put(XpCache.key(name.getAsString()), total.getAsLong());
				}
			}
		}

		return new GroupResult(true, exp, null);
	}

	static String userAgent(String contact)
	{
		String agent = "ClanPromotionHelper (RuneLite plugin)";
		if (contact != null && !contact.trim().isEmpty())
		{
			agent += "; contact: " + contact.trim();
		}
		return agent;
	}

	static Result parse(int code, String body, String retryAfterHeader, Gson gson)
	{
		if (code == 429)
		{
			return Result.retry(parseRetryAfter(retryAfterHeader), "Rate limited by Wise Old Man");
		}

		if (code >= 500)
		{
			return Result.retry(SERVER_ERROR_WAIT_SECONDS, "Wise Old Man returned HTTP " + code);
		}

		JsonObject root;
		try
		{
			root = gson.fromJson(body, JsonObject.class);
		}
		catch (JsonParseException | IllegalStateException e)
		{
			root = null;
		}

		if (code < 200 || code >= 300)
		{
			String message = root != null && root.has("message") && root.get("message").isJsonPrimitive()
				? root.get("message").getAsString()
				: "Wise Old Man returned HTTP " + code;
			return Result.failed(message);
		}

		JsonElement gained = path(root, "data", "skills", "overall", "experience", "gained");
		if (gained == null || !gained.isJsonPrimitive() || !gained.getAsJsonPrimitive().isNumber())
		{
			return Result.failed("Unexpected Wise Old Man response (no overall XP data)");
		}

		JsonElement start = path(root, "data", "skills", "overall", "experience", "start");
		Long startXp = start != null && start.isJsonPrimitive() && start.getAsJsonPrimitive().isNumber() && start.getAsLong() >= 0
			? start.getAsLong()
			: null;

		return Result.ok(gained.getAsLong(), startXp);
	}

	private static int parseRetryAfter(String header)
	{
		if (header != null)
		{
			try
			{
				int seconds = Integer.parseInt(header.trim());
				if (seconds > 0)
				{
					return seconds;
				}
			}
			catch (NumberFormatException e)
			{
				// Fall back to the default wait
			}
		}
		return DEFAULT_RATE_LIMIT_WAIT_SECONDS;
	}

	private static JsonElement path(JsonObject root, String... keys)
	{
		JsonElement current = root;
		for (String key : keys)
		{
			if (current == null || !current.isJsonObject())
			{
				return null;
			}
			current = current.getAsJsonObject().get(key);
		}
		return current;
	}
}

package com.clanpromotionhelper;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.time.LocalDate;
import java.util.Collection;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Remembers each member's XP gained since joining, so members are only looked up again
 * once their entry is older than the refresh interval or their join date changes.
 */
class XpCache
{
	private static final Type MAP_TYPE = new TypeToken<Map<String, Entry>>()
	{
	}.getType();

	@Data
	@NoArgsConstructor
	@AllArgsConstructor
	static class Entry
	{
		/** XP gained since joining; null when the last lookup failed */
		Long xpGained;
		long fetchedAt;
		String joinDate;
		String error;
		/**
		 * The member's total XP when their join-date window starts, from Wise Old Man. It belongs to this
		 * name and join date permanently, so it is kept across refreshes and lets a single group request
		 * work out everyone's XP gained. Null when unknown (including caches saved by older versions).
		 */
		Long baselineXp;

		Entry(Long xpGained, long fetchedAt, String joinDate, String error)
		{
			this(xpGained, fetchedAt, joinDate, error, null);
		}
	}

	private final Map<String, Entry> entries = new ConcurrentHashMap<>();

	/**
	 * Matches names the way Wise Old Man does: case-insensitive, with spaces, underscores, hyphens and
	 * non-breaking spaces all treated as the same character.
	 */
	static String key(String rsn)
	{
		// A plain loop rather than regular expressions: this runs for every member on every roster
		// check and every frame the member list is open
		StringBuilder key = new StringBuilder(rsn.length());
		boolean pendingSpace = false;
		for (int i = 0; i < rsn.length(); i++)
		{
			char c = rsn.charAt(i);
			if (c == ' ' || c == '\u00A0' || c == '_' || c == '-')
			{
				pendingSpace = key.length() > 0;
			}
			else
			{
				if (pendingSpace)
				{
					key.append(' ');
					pendingSpace = false;
				}
				key.append(c);
			}
		}
		return key.toString().trim().toLowerCase(Locale.ROOT);
	}

	Entry get(String rsn)
	{
		return entries.get(key(rsn));
	}

	void put(String rsn, Entry entry)
	{
		entries.put(key(rsn), entry);
	}

	int size()
	{
		return entries.size();
	}

	/** Whether the member has no result for their join date, or only one fetched before {@code refreshBefore}. */
	boolean needsFetch(String rsn, LocalDate joinDate, long refreshBefore)
	{
		Entry entry = get(rsn);
		if (entry == null || !joinDate.toString().equals(entry.getJoinDate()))
		{
			return true;
		}
		return entry.getFetchedAt() < refreshBefore;
	}

	/** The saved baseline for this member, or null if there isn't one for their current join date. */
	Long baselineFor(String rsn, LocalDate joinDate)
	{
		Entry entry = get(rsn);
		if (entry == null || entry.getBaselineXp() == null || !joinDate.toString().equals(entry.getJoinDate()))
		{
			return null;
		}
		return entry.getBaselineXp();
	}

	/**
	 * Works out a member's XP gained from their current total in a Wise Old Man group, using the saved
	 * baseline. Returns false, leaving the member to be looked up individually, when there's no baseline,
	 * the group has no usable total for them, or the total is below the baseline.
	 */
	boolean applyGroupXp(String rsn, LocalDate joinDate, Map<String, Long> groupExp, long nowMillis)
	{
		Long baseline = baselineFor(rsn, joinDate);
		Long current = groupExp.get(key(rsn));
		if (baseline == null || current == null || current <= 0 || current < baseline)
		{
			return false;
		}

		put(rsn, new Entry(current - baseline, nowMillis, joinDate.toString(), null, baseline));
		return true;
	}

	/** Drops members who are no longer in the clan. */
	void retainOnly(Collection<String> rsns)
	{
		Set<String> keep = new HashSet<>();
		for (String rsn : rsns)
		{
			keep.add(key(rsn));
		}
		entries.keySet().retainAll(keep);
	}

	String toJson(Gson gson)
	{
		return gson.toJson(entries, MAP_TYPE);
	}

	static XpCache fromJson(String json, Gson gson)
	{
		XpCache cache = new XpCache();
		if (json == null || json.isEmpty())
		{
			return cache;
		}

		try
		{
			Map<String, Entry> loaded = gson.fromJson(json, MAP_TYPE);
			if (loaded != null)
			{
				for (Map.Entry<String, Entry> saved : loaded.entrySet())
				{
					// The cache can't hold nulls, so skip any a damaged save left behind
					if (saved.getKey() != null && saved.getValue() != null)
					{
						cache.entries.put(saved.getKey(), saved.getValue());
					}
				}
			}
		}
		catch (JsonParseException e)
		{
			// A corrupt cache just means everyone is looked up again
		}
		return cache;
	}
}

