package com.clanpromotionhelper;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.time.LocalDate;
import org.junit.Test;

public class RankRulesTest
{
	private static final LocalDate TODAY = LocalDate.of(2026, 10, 24);
	private final RankRules rules = RankRules.parse(RankRules.DEFAULT_TABLE);

	@Test
	public void defaultTableHasAllRanks()
	{
		assertEquals(13, rules.getRanks().size());
		assertEquals("Thief", rules.getRanks().get(0).getName());
		assertEquals("Marshal", rules.getRanks().get(12).getName());
	}

	@Test
	public void admiralWithEnoughXpAndTimeBecomesMarshal()
	{
		assertEquals("Marshal", rules.nextRankFor("Admiral", LocalDate.of(2024, 3, 31), 80_000_000L, TODAY));
	}

	@Test
	public void recruitWithEnoughXpAndTimeBecomesCorporal()
	{
		assertEquals("Corporal", rules.nextRankFor("Recruit", LocalDate.of(2026, 8, 1), 600_000L, TODAY));
	}

	@Test
	public void rankMatchIsCaseInsensitive()
	{
		assertEquals("Lieutenant", rules.nextRankFor("sergeant", LocalDate.of(2025, 1, 1), 2_500_000L, TODAY));
	}

	@Test
	public void notEnoughXpMeansNoPromotion()
	{
		assertNull(rules.nextRankFor("Recruit", LocalDate.of(2025, 7, 26), 1_000L, TODAY));
	}

	@Test
	public void notEnoughTimeMeansNoPromotion()
	{
		assertNull(rules.nextRankFor("Recruit", LocalDate.of(2026, 10, 1), 50_000_000L, TODAY));
	}

	@Test
	public void missingXpMeansNoPromotion()
	{
		assertNull(rules.nextRankFor("Recruit", LocalDate.of(2024, 1, 1), null, TODAY));
	}

	@Test
	public void topRankHasNoPromotion()
	{
		assertNull(rules.nextRankFor("Marshal", LocalDate.of(2020, 1, 1), 500_000_000L, TODAY));
	}

	@Test
	public void unknownRankHasNoPromotion()
	{
		assertNull(rules.nextRankFor("Owner", LocalDate.of(2020, 1, 1), 500_000_000L, TODAY));
	}

	@Test
	public void monthCountsOnlyOnceTheJoinDayArrives()
	{
		// Joined the 25th: on the 24th of a later month the last month isn't complete yet
		assertEquals(1, RankRules.monthsInClan(LocalDate.of(2026, 8, 25), TODAY));
		assertEquals(2, RankRules.monthsInClan(LocalDate.of(2026, 8, 24), TODAY));
		assertEquals(0, RankRules.monthsInClan(LocalDate.of(2026, 10, 25), TODAY));
	}

	@Test
	public void monthBoundaryDecidesPromotion()
	{
		// Corporal needs 2 months: joined 2026-08-25 is only 1 full month on 2026-10-24
		assertNull(rules.nextRankFor("Recruit", LocalDate.of(2026, 8, 25), 600_000L, TODAY));
		assertEquals("Corporal", rules.nextRankFor("Recruit", LocalDate.of(2026, 8, 24), 600_000L, TODAY));
	}

	@Test
	public void customTableSkipsBadLines()
	{
		RankRules custom = RankRules.parse("Bronze:0:0\n\nnot a rank\nSilver:x:1\nGold:1:0.5\n");
		assertEquals(2, custom.getRanks().size());
		assertEquals("Gold", custom.nextRankFor("Bronze", LocalDate.of(2026, 9, 1), 500_000L, TODAY));
	}

	@Test
	public void skippedLinesAreReportedWithTheirLineNumber()
	{
		RankRules custom = RankRules.parse("Bronze:0:0\n\nnot a rank\nSilver:x:1\nGold:-1:0.5\nPlatinum:1:NaN");
		assertEquals(1, custom.getRanks().size());
		assertEquals(4, custom.getErrors().size());
		assertTrue(custom.getErrors().get(0).startsWith("Line 3 (not a rank)"));
		assertTrue(custom.getErrors().get(1).startsWith("Line 4 (Silver:x:1)"));
		assertTrue(custom.getErrors().get(2).endsWith("numbers can't be negative"));
		assertTrue(custom.getErrors().get(3).startsWith("Line 6"));
	}

	@Test
	public void defaultTableHasNoErrors()
	{
		assertTrue(rules.getErrors().isEmpty());
	}

	@Test
	public void onlyLadderRanksBelowTheTopCanBePromoted()
	{
		assertTrue(rules.canBePromoted("Recruit"));
		assertTrue(rules.canBePromoted("admiral"));
		assertFalse(rules.canBePromoted("Marshal"));
		assertFalse(rules.canBePromoted("Owner"));
		assertFalse(rules.canBePromoted(null));
	}

	@Test
	public void evaluateReportsEachStatus()
	{
		assertEquals(PromotionStatus.READY,
			rules.evaluate("Admiral", LocalDate.of(2024, 3, 31), 80_000_000L, TODAY).getStatus());
		assertEquals(PromotionStatus.NOT_READY,
			rules.evaluate("Recruit", LocalDate.of(2025, 7, 26), 1_000L, TODAY).getStatus());
		assertEquals(PromotionStatus.NO_XP,
			rules.evaluate("Recruit", LocalDate.of(2024, 1, 1), null, TODAY).getStatus());
		assertEquals(PromotionStatus.MAX_RANK,
			rules.evaluate("Marshal", LocalDate.of(2020, 1, 1), 500_000_000L, TODAY).getStatus());
		assertEquals(PromotionStatus.UNKNOWN_RANK,
			rules.evaluate("Owner", LocalDate.of(2020, 1, 1), 500_000_000L, TODAY).getStatus());
		assertEquals(PromotionStatus.UNKNOWN_RANK,
			rules.evaluate(null, LocalDate.of(2020, 1, 1), 500_000_000L, TODAY).getStatus());
	}

	@Test
	public void evaluateIncludesNextRankAndRequirementsEvenWhenNotReady()
	{
		RankRules.Evaluation evaluation = rules.evaluate("Recruit", LocalDate.of(2026, 10, 1), 50_000_000L, TODAY);
		assertEquals(PromotionStatus.NOT_READY, evaluation.getStatus());
		assertEquals("Corporal", evaluation.getNextRank());
		assertEquals(0, evaluation.getMonths());
		assertEquals(2, evaluation.getRequiredMonths());
		assertEquals(0.5, evaluation.getRequiredXpMillions(), 0.0001);
	}
}

package com.clanpromotionhelper;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class TimeAgoTest
{
	private static final long NOW = 1_800_000_000_000L;

	@Test
	public void underAMinuteIsJustNow()
	{
		assertEquals("just now", TimeAgo.format(NOW, NOW));
		assertEquals("just now", TimeAgo.format(NOW, NOW - 59_000));
	}

	@Test
	public void minutesHoursAndDays()
	{
		assertEquals("1 min ago", TimeAgo.format(NOW, NOW - 60_000));
		assertEquals("59 min ago", TimeAgo.format(NOW, NOW - 59 * 60_000));
		assertEquals("1 h ago", TimeAgo.format(NOW, NOW - 3_600_000));
		assertEquals("23 h ago", TimeAgo.format(NOW, NOW - 23 * 3_600_000L));
		assertEquals("2 d ago", TimeAgo.format(NOW, NOW - 2 * 86_400_000L));
	}

	@Test
	public void aTimeInTheFutureIsJustNow()
	{
		assertEquals("just now", TimeAgo.format(NOW, NOW + 5_000));
	}
}

package com.clanpromotionhelper;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.clanpromotionhelper.WiseOldManClient.Result;
import com.google.gson.Gson;
import org.junit.Test;

public class WiseOldManClientTest
{
	private final Gson gson = new Gson();

	@Test
	public void successReturnsOverallXpGained()
	{
		Result result = WiseOldManClient.parse(200,
			"{\"data\":{\"skills\":{\"overall\":{\"experience\":{\"gained\":5000000}}}}}", null, gson);
		assertEquals(Result.Status.OK, result.getStatus());
		assertEquals(Long.valueOf(5_000_000L), result.getXpGained());
	}

	@Test
	public void zeroGainedIsStillASuccess()
	{
		Result result = WiseOldManClient.parse(200,
			"{\"data\":{\"skills\":{\"overall\":{\"experience\":{\"gained\":0}}}}}", null, gson);
		assertEquals(Result.Status.OK, result.getStatus());
		assertEquals(Long.valueOf(0L), result.getXpGained());
	}

	@Test
	public void notFoundIsAFailureNotZeroXp()
	{
		Result result = WiseOldManClient.parse(404, "{\"message\":\"Player not found.\"}", null, gson);
		assertEquals(Result.Status.FAILED, result.getStatus());
		assertNull(result.getXpGained());
		assertEquals("Player not found.", result.getError());
	}

	@Test
	public void rateLimitRetriesAfterHeader()
	{
		Result result = WiseOldManClient.parse(429, "{\"message\":\"Too many requests\"}", "12", gson);
		assertEquals(Result.Status.RETRY, result.getStatus());
		assertEquals(12, result.getRetryAfterSeconds());
	}

	@Test
	public void rateLimitWithoutHeaderWaitsAMinute()
	{
		Result result = WiseOldManClient.parse(429, "", null, gson);
		assertEquals(Result.Status.RETRY, result.getStatus());
		assertEquals(60, result.getRetryAfterSeconds());
	}

	@Test
	public void serverErrorRetries()
	{
		Result result = WiseOldManClient.parse(503, "<html>down</html>", null, gson);
		assertEquals(Result.Status.RETRY, result.getStatus());
	}

	@Test
	public void missingOverallXpIsAFailure()
	{
		Result result = WiseOldManClient.parse(200, "{\"data\":{\"skills\":{}}}", null, gson);
		assertEquals(Result.Status.FAILED, result.getStatus());
		assertNull(result.getXpGained());
	}

	@Test
	public void nonJsonSuccessIsAFailure()
	{
		Result result = WiseOldManClient.parse(200, "not json", null, gson);
		assertEquals(Result.Status.FAILED, result.getStatus());
	}

	@Test
	public void userAgentIncludesContactWhenSet()
	{
		assertEquals("ClanPromotionHelper (RuneLite plugin); contact: Player#1234", WiseOldManClient.userAgent(" Player#1234 "));
		assertEquals("ClanPromotionHelper (RuneLite plugin)", WiseOldManClient.userAgent(""));
	}

	// Trimmed from a real Wise Old Man /players/{name}/gained response
	private static final String REAL_PLAYER_GAINED = "{\"startsAt\":\"2025-01-01T10:43:42.703Z\",\"endsAt\":\"2026-10-23T06:44:13.987Z\","
		+ "\"data\":{\"skills\":{\"overall\":{\"metric\":\"overall\",\"experience\":{\"gained\":260267325,\"start\":182870123,\"end\":443137448}}}}}";

	// Trimmed from a real Wise Old Man /groups/{id} response
	private static final String REAL_GROUP = "{\"id\":6371,\"memberCount\":3,\"memberships\":["
		+ "{\"playerId\":1,\"role\":\"member\",\"player\":{\"username\":\"vghosted\",\"displayName\":\"vghosted\",\"exp\":443293491,\"status\":\"active\"}},"
		+ "{\"playerId\":2,\"role\":\"member\",\"player\":{\"username\":\"ghosted kate\",\"displayName\":\"Ghosted Kate\",\"exp\":12345678}},"
		+ "{\"playerId\":3,\"role\":\"member\",\"player\":{\"username\":\"untracked guy\",\"displayName\":\"Untracked_Guy\",\"exp\":0}}]}";

	@Test
	public void realPlayerResponseGivesGainedAndBaseline()
	{
		Result result = WiseOldManClient.parse(200, REAL_PLAYER_GAINED, null, gson);
		assertEquals(Result.Status.OK, result.getStatus());
		assertEquals(Long.valueOf(260_267_325L), result.getXpGained());
		assertEquals(Long.valueOf(182_870_123L), result.getStartXp());
	}

	@Test
	public void missingOrNegativeStartMeansNoBaseline()
	{
		Result missing = WiseOldManClient.parse(200,
			"{\"data\":{\"skills\":{\"overall\":{\"experience\":{\"gained\":5}}}}}", null, gson);
		assertNull(missing.getStartXp());

		Result negative = WiseOldManClient.parse(200,
			"{\"data\":{\"skills\":{\"overall\":{\"experience\":{\"gained\":5,\"start\":-1,\"end\":9}}}}}", null, gson);
		assertEquals(Long.valueOf(5L), negative.getXpGained());
		assertNull(negative.getStartXp());
	}

	@Test
	public void groupResponseIsKeyedByUsernameAndDisplayName()
	{
		WiseOldManClient.GroupResult result = WiseOldManClient.parseGroup(200, REAL_GROUP, gson);
		assertTrue(result.isOk());
		assertEquals(Long.valueOf(443_293_491L), result.getExp().get(XpCache.key("vghosted")));
		assertEquals(Long.valueOf(12_345_678L), result.getExp().get(XpCache.key("ghosted kate")));
		assertEquals(Long.valueOf(12_345_678L), result.getExp().get(XpCache.key("Ghosted Kate")));
	}

	@Test
	public void groupMembersWithZeroExpAreLeftOut()
	{
		WiseOldManClient.GroupResult result = WiseOldManClient.parseGroup(200, REAL_GROUP, gson);
		assertNull(result.getExp().get(XpCache.key("untracked guy")));
		assertNull(result.getExp().get(XpCache.key("Untracked_Guy")));
	}

	@Test
	public void groupNamesMatchAcrossUnderscoresAndHyphens()
	{
		WiseOldManClient.GroupResult result = WiseOldManClient.parseGroup(200,
			"{\"memberships\":[{\"player\":{\"username\":\"zezima x\",\"displayName\":\"Zezima-X\",\"exp\":10}}]}", gson);
		assertEquals(Long.valueOf(10L), result.getExp().get(XpCache.key("Zezima_X")));
		assertEquals(Long.valueOf(10L), result.getExp().get(XpCache.key("zezima x")));
	}

	@Test
	public void groupNotFoundIsAFailureWithTheServersMessage()
	{
		WiseOldManClient.GroupResult result = WiseOldManClient.parseGroup(404, "{\"message\":\"Group not found.\"}", gson);
		assertFalse(result.isOk());
		assertEquals("Group not found.", result.getError());
	}

	@Test
	public void groupRateLimitIsAFailureNotARetry()
	{
		WiseOldManClient.GroupResult result = WiseOldManClient.parseGroup(429, "", gson);
		assertFalse(result.isOk());
		assertEquals("Rate limited by Wise Old Man", result.getError());
	}

	@Test
	public void groupWithoutMembershipsIsAFailure()
	{
		assertFalse(WiseOldManClient.parseGroup(200, "{\"id\":1}", gson).isOk());
		assertFalse(WiseOldManClient.parseGroup(200, "not json", gson).isOk());
	}
}

package com.clanpromotionhelper;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.time.LocalDate;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import org.junit.Test;

public class XpCacheTest
{
	private static final LocalDate JOINED = LocalDate.of(2024, 3, 31);
	private static final long NOW = 1_800_000_000_000L;
	/** Start of the day the player logged in: results from before then are due their daily refresh */
	private static final long TODAY_START = NOW - TimeUnit.HOURS.toMillis(4);
	private final Gson gson = new Gson();

	@Test
	public void unknownMemberNeedsFetch()
	{
		assertTrue(new XpCache().needsFetch("2006 Buffon", JOINED, TODAY_START));
	}

	@Test
	public void entryFromTodayDoesNotNeedFetch()
	{
		XpCache cache = new XpCache();
		cache.put("2006 Buffon", new XpCache.Entry(80_000_000L, NOW - TimeUnit.HOURS.toMillis(1), JOINED.toString(), null));
		assertFalse(cache.needsFetch("2006 Buffon", JOINED, TODAY_START));
	}

	@Test
	public void entryFromBeforeTodayNeedsFetch()
	{
		XpCache cache = new XpCache();
		cache.put("2006 Buffon", new XpCache.Entry(80_000_000L, NOW - TimeUnit.HOURS.toMillis(6), JOINED.toString(), null));
		assertTrue(cache.needsFetch("2006 Buffon", JOINED, TODAY_START));
	}

	@Test
	public void changedJoinDateNeedsFetch()
	{
		XpCache cache = new XpCache();
		cache.put("2006 Buffon", new XpCache.Entry(80_000_000L, NOW, JOINED.toString(), null));
		assertTrue(cache.needsFetch("2006 Buffon", JOINED.plusDays(1), TODAY_START));
	}

	@Test
	public void failedLookupWaitsForTheNextRefresh()
	{
		XpCache cache = new XpCache();
		cache.put("Missing", new XpCache.Entry(null, NOW, JOINED.toString(), "Player not found."));
		assertFalse(cache.needsFetch("Missing", JOINED, TODAY_START));
	}

	@Test
	public void namesMatchIgnoringCaseAndNonBreakingSpaces()
	{
		XpCache cache = new XpCache();
		cache.put("2006\u00A0Buffon", new XpCache.Entry(1L, NOW, JOINED.toString(), null));
		assertEquals(Long.valueOf(1L), cache.get("2006 buffon").getXpGained());
	}

	@Test
	public void retainOnlyDropsMembersWhoLeft()
	{
		XpCache cache = new XpCache();
		cache.put("Stays", new XpCache.Entry(1L, NOW, JOINED.toString(), null));
		cache.put("Left", new XpCache.Entry(1L, NOW, JOINED.toString(), null));
		cache.retainOnly(Arrays.asList("stays"));
		assertEquals(1, cache.size());
		assertNull(cache.get("Left"));
	}

	@Test
	public void survivesJsonRoundTrip()
	{
		XpCache cache = new XpCache();
		cache.put("2006 Buffon", new XpCache.Entry(80_000_000L, NOW, JOINED.toString(), null));
		cache.put("Missing", new XpCache.Entry(null, NOW, JOINED.toString(), "Player not found."));

		XpCache loaded = XpCache.fromJson(cache.toJson(gson), gson);
		assertEquals(Long.valueOf(80_000_000L), loaded.get("2006 Buffon").getXpGained());
		assertEquals("Player not found.", loaded.get("Missing").getError());
		assertNull(loaded.get("Missing").getXpGained());
	}

	@Test
	public void corruptJsonGivesEmptyCache()
	{
		assertEquals(0, XpCache.fromJson("{not json", gson).size());
		assertEquals(0, XpCache.fromJson(null, gson).size());
	}

	private static Map<String, Long> group(Object... pairs)
	{
		Map<String, Long> map = new HashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			map.put(XpCache.key((String) pairs[i]), (Long) pairs[i + 1]);
		}
		return map;
	}

	private static XpCache.Entry withBaseline(long gained, long baseline, long fetchedAt)
	{
		return new XpCache.Entry(gained, fetchedAt, JOINED.toString(), null, baseline);
	}

	@Test
	public void namesMatchAcrossUnderscoresHyphensAndRepeatedSpaces()
	{
		assertEquals(XpCache.key("Zezima X"), XpCache.key("zezima_x"));
		assertEquals(XpCache.key("Zezima X"), XpCache.key("ZEZIMA-X"));
		assertEquals(XpCache.key("Zezima X"), XpCache.key(" zezima  x "));
	}

	@Test
	public void baselineSurvivesTheRefreshInterval()
	{
		XpCache cache = new XpCache();
		long old = NOW - TimeUnit.HOURS.toMillis(30);
		cache.put("2006 Buffon", withBaseline(80_000_000L, 100_000_000L, old));

		// Stale, so it needs refreshing, but the baseline is still there to refresh it with
		assertTrue(cache.needsFetch("2006 Buffon", JOINED, TODAY_START));
		assertEquals(Long.valueOf(100_000_000L), cache.baselineFor("2006 Buffon", JOINED));
	}

	@Test
	public void baselineIsIgnoredWhenTheJoinDateChanges()
	{
		XpCache cache = new XpCache();
		cache.put("2006 Buffon", withBaseline(1L, 5L, NOW));
		assertNull(cache.baselineFor("2006 Buffon", JOINED.plusDays(1)));
	}

	@Test
	public void groupXpIsCurrentTotalMinusBaseline()
	{
		XpCache cache = new XpCache();
		cache.put("2006 Buffon", withBaseline(1L, 100_000_000L, NOW - TimeUnit.HOURS.toMillis(30)));

		assertTrue(cache.applyGroupXp("2006 Buffon", JOINED, group("2006 buffon", 180_000_000L), NOW));
		XpCache.Entry entry = cache.get("2006 Buffon");
		assertEquals(Long.valueOf(80_000_000L), entry.getXpGained());
		assertEquals(NOW, entry.getFetchedAt());
		assertEquals(Long.valueOf(100_000_000L), entry.getBaselineXp());
		assertFalse(cache.needsFetch("2006 Buffon", JOINED, TODAY_START));
	}

	@Test
	public void groupXpNeedsABaseline()
	{
		XpCache cache = new XpCache();
		cache.put("NoBaseline", new XpCache.Entry(5L, NOW - TimeUnit.HOURS.toMillis(30), JOINED.toString(), null));
		assertFalse(cache.applyGroupXp("NoBaseline", JOINED, group("NoBaseline", 9L), NOW));
		assertFalse(cache.applyGroupXp("NeverSeen", JOINED, group("NeverSeen", 9L), NOW));
	}

	@Test
	public void groupXpSkipsMembersTheGroupCannotAnswerFor()
	{
		XpCache cache = new XpCache();
		long old = NOW - TimeUnit.HOURS.toMillis(30);
		cache.put("NotInGroup", withBaseline(1L, 100L, old));
		cache.put("ZeroExp", withBaseline(1L, 100L, old));
		cache.put("BelowBaseline", withBaseline(1L, 100L, old));

		Map<String, Long> exp = group("ZeroExp", 0L, "BelowBaseline", 50L);
		assertFalse(cache.applyGroupXp("NotInGroup", JOINED, exp, NOW));
		assertFalse(cache.applyGroupXp("ZeroExp", JOINED, exp, NOW));
		assertFalse(cache.applyGroupXp("BelowBaseline", JOINED, exp, NOW));
		// Left untouched, so they stay stale and get an individual lookup
		assertTrue(cache.needsFetch("NotInGroup", JOINED, TODAY_START));
		assertTrue(cache.needsFetch("BelowBaseline", JOINED, TODAY_START));
	}

	@Test
	public void cachesSavedBeforeBaselinesExistLoadWithoutOne()
	{
		String oldJson = "{\"2006 buffon\":{\"xpGained\":80000000,\"fetchedAt\":1800000000000,\"joinDate\":\"2024-03-31\"}}";
		XpCache loaded = XpCache.fromJson(oldJson, gson);
		assertEquals(Long.valueOf(80_000_000L), loaded.get("2006 Buffon").getXpGained());
		assertNull(loaded.baselineFor("2006 Buffon", JOINED));
	}

	@Test
	public void baselineSurvivesJsonRoundTrip()
	{
		XpCache cache = new XpCache();
		cache.put("2006 Buffon", withBaseline(80_000_000L, 100_000_000L, NOW));
		XpCache loaded = XpCache.fromJson(cache.toJson(gson), gson);
		assertEquals(Long.valueOf(100_000_000L), loaded.baselineFor("2006 Buffon", JOINED));
	}

	@Test
	public void namesIgnoreLeadingTrailingAndRepeatedSeparators()
	{
		assertEquals("zezima x", XpCache.key("__Zezima--X__ "));
		assertEquals("zezima x", XpCache.key("\u00A0Zezima\u00A0\u00A0X"));
		assertEquals("a b c", XpCache.key("A_-_B   C"));
	}

	@Test
	public void emptyAndSeparatorOnlyNamesGiveAnEmptyKey()
	{
		assertEquals("", XpCache.key(""));
		assertEquals("", XpCache.key(" _-\u00A0"));
	}

	@Test
	public void digitsAndMixedCaseAreKept()
	{
		assertEquals("2006 buffon", XpCache.key("2006 Buffon"));
		assertEquals("618 ironman", XpCache.key("618_IRONMAN"));
	}

	@Test
	public void damagedSaveWithNullEntriesStillLoads()
	{
		String json = "{\"good\":{\"xpGained\":5,\"fetchedAt\":1,\"joinDate\":\"2024-03-31\"},\"bad\":null}";
		XpCache loaded = XpCache.fromJson(json, gson);
		assertEquals(1, loaded.size());
		assertEquals(Long.valueOf(5L), loaded.get("good").getXpGained());
	}
}
